let $links = null;
let $nodes = null;
let $letters = null;
let $labels = null;
let $annotations = null;
const anno = {
key: ' brin',
text: 'of people type "n" at this point'
};
// helper functions
function stack(x) {
const xobj = {};
const sum = d3.sum(x.children, d => d.h);
x.children.forEach(d => (xobj[d.data.char] = d.h / sum));
return d3.stack().keys(Object.keys(xobj))([xobj]);
}
